import{_ as o,o as t,c as n,ah as r}from"./chunks/framework.Dooi6hgo.js";const s="/projects/6-Channel-Servo-Tester/en/latest/assets/image2.C1jGJJ0x.jpeg",a="/projects/6-Channel-Servo-Tester/en/latest/assets/image3.CPFCFgJH.jpeg",i="/projects/6-Channel-Servo-Tester/en/latest/assets/image4.-GQRQmfo.jpeg",c="/projects/6-Channel-Servo-Tester/en/latest/assets/image5.BPkDf_SE.jpeg",l="/projects/6-Channel-Servo-Tester/en/latest/assets/image6.Bp-6KFYP.png",h="/projects/6-Channel-Servo-Tester/en/latest/assets/image7.BLSEpxYm.png",d="/projects/6-Channel-Servo-Tester/en/latest/assets/image8.qHOl4Tm8.png",p="/projects/6-Channel-Servo-Tester/en/latest/assets/image9.7LmActMk.png",g="/projects/6-Channel-Servo-Tester/en/latest/assets/image10.ZIDb0dmw.png",m="/projects/6-Channel-Servo-Tester/en/latest/assets/image11.BBm0IVvc.png",_="/projects/6-Channel-Servo-Tester/en/latest/assets/image12.BslGNGBb.png",w="/projects/6-Channel-Servo-Tester/en/latest/assets/image13.CsyzRlgM.png",u="/projects/6-Channel-Servo-Tester/en/latest/assets/image14.Dwy9oWEL.png",j=JSON.parse('{"title":"2. 6 channel knob servo controller","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2.6_channel_knob_servo_controller.md","filePath":"docs/2.6_channel_knob_servo_controller.md"}'),b={name:"docs/2.6_channel_knob_servo_controller.md"};function v(f,e,k,y,T,C){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="_2-6-channel-knob-servo-controller" tabindex="-1">2. 6 channel knob servo controller <a class="header-anchor" href="#_2-6-channel-knob-servo-controller" aria-label="Permalink to &quot;2. 6 channel knob servo controller&quot;">​</a></h1><img loading="lazy" height="1000" width="1000" src="'+s+'" class="common_img" style="width:400px;"><h2 id="_2-1-overview" tabindex="-1">2.1 Overview <a class="header-anchor" href="#_2-1-overview" aria-label="Permalink to &quot;2.1 Overview&quot;">​</a></h2><img loading="lazy" height="348" width="464" src="'+a+'" class="common_img"><p>The working voltage range of 6 channel knob servo controller(controller) is 5V-8.4V. Users can select the power supply to supply power to the controller according to the voltage required by the servos. Excessive voltage can damage the controller and servo, causing some unresolved faults. In this paper, a 7.4V lithium battery is used as the power source.</p><h2 id="_2-2-wiring" tabindex="-1">2.2 wiring <a class="header-anchor" href="#_2-2-wiring" aria-label="Permalink to &quot;2.2 wiring&quot;">​</a></h2><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Using the 7.4V lithium battery, if it is used to control our company&#39;s <code>LDX-218</code> and <code>LDX-227</code> servos, see section B directly.</p></section><p class="common_img" style="text-align:center;"><img loading="lazy" height="329" width="327" src="'+i+'" style="width:325px;"><img loading="lazy" height="327" width="325" src="'+c+'" style="width:325px;"></p><p>If it is used to control other standard servos, please decide whether to use the step-down chip according to the nominal parameters such as its rated voltage. The step-down chip can provide a voltage drop of 1.4V. If it is used to control mechanical arm, it must be connected to the step-down chip.Please refer to part A for the wiring diagram of the step-down chip.</p><img loading="lazy" height="119" width="518" src="'+l+'" class="common_img"><h3 id="_2-2-1-part-a-buck-chip-connection" tabindex="-1">2.2.1 Part A (Buck Chip Connection) <a class="header-anchor" href="#_2-2-1-part-a-buck-chip-connection" aria-label="Permalink to &quot;2.2.1 Part A (Buck Chip Connection)&quot;">​</a></h3><p>Using a buck chip to connect the controller to the battery:</p><img loading="lazy" height="351" width="662" src="'+h+'" class="common_img"><p>The buck chip is installed to the Controller, the red line corresponds to the Blue power supply terminal of the controller <code>+</code> interface, and the black line corresponds controller Blue Power Terminal <code>-</code> interface. The servo is inserted into the servo socket of the controller, and the <code>+</code>, <code>-</code>, <code>s</code> should correspond to each other, as shown in figure:</p><img loading="lazy" height="403" width="674" src="'+d+'" class="common_img"><p>Then connect the battery and the power indicator on the controller lights up after power-on. As shown below:</p><img loading="lazy" height="514" width="669" src="'+p+'" class="common_img"><h3 id="_2-2-2-part-b-using-power-pair-wiring-to-connect-the-controller-to-the-battery" tabindex="-1">2.2.2 Part B: Using power-pair wiring to connect the controller to the battery <a class="header-anchor" href="#_2-2-2-part-b-using-power-pair-wiring-to-connect-the-controller-to-the-battery" aria-label="Permalink to &quot;2.2.2 Part B: Using power-pair wiring to connect the controller to the battery&quot;">​</a></h3><p>The power supply wiring is as shown:</p><img loading="lazy" height="422" width="573" src="'+g+'" class="common_img"><p>We should install the power supply wiring to the controller, the red line corresponds to the <code>+</code> interface of the blue power supply terminal of the controller, and the black line corresponds to the control blue power terminal <code>-</code> interface. Insert the servo into the servo jack of the controller. The <code>+</code>, <code>-</code>, <code>s</code> should be one-to-one correspondence, as shown in the figure:</p><img loading="lazy" height="474" width="636" src="'+m+'" class="common_img"><p>Then connect the battery and the power indicator on the controller lights up after power-on. As shown below:</p><img loading="lazy" height="414" width="640" src="'+_+'" class="common_img"><h2 id="_2-3-operation" tabindex="-1">2.3 Operation <a class="header-anchor" href="#_2-3-operation" aria-label="Permalink to &quot;2.3 Operation&quot;">​</a></h2><p>Rotate the knob with the corresponding number of the port number. If the servo is inserted into the 0-position jack, rotate the <code>S0</code> knob, and the rudder will rotate with the rotation of the knob.</p><img loading="lazy" height="518" width="831" src="'+w+'" class="common_img"><p>Press the button of the corresponding number servo on the controller.For example, if the servo is connected to the No.0 port, please press the <code>S0</code> button, then the servo will rotate to the <code>1500</code> position, which is the middle position. It&#39;s in the middle at the servo rotation range. At this situation, the <code>S0</code> knob doesn&#39;t work until the middle button is pressed again, and the knob control will be restored.And the servo will rotate to the setting position of the knob.</p><img loading="lazy" height="252" width="830" src="'+u+'" class="common_img">',29)])])}const P=o(b,[["render",v]]);export{j as __pageData,P as default};
